export function translateNarrative(text, language) {
  if (language !== 'my' || typeof text !== 'string') return text;
  if (EXACT[text]) return EXACT[text];
  for (const [pattern, translated] of TEMPLATES) {
    const match = pattern.exec(text);
    if (match) return translated.replace(/\{(\d+)\}/g, (_, index) => match[Number(index) + 1]);
  }
  return text;
}
